class Solution {
    private int ans = 0;
    private int dfs(TreeNode node) {
        if (node == null) return 0;
        int left = dfs(node.left);
        int right = dfs(node.right);
        int leftArrow = (node.left != null && node.left.val == node.val) ? left + 1 : 0;
        int rightArrow = (node.right != null && node.right.val == node.val) ? right + 1 : 0;
        ans = Math.max(ans, leftArrow + rightArrow);
        return Math.max(leftArrow, rightArrow);
    }
    public int longestUnivaluePath(TreeNode root) {
        ans = 0;
        dfs(root);
        return ans;
    }
}

var longestUnivaluePath = function(root) {
    let ans = 0;
    function dfs(node) {
        if (!node) return 0;
        const left = dfs(node.left);
        const right = dfs(node.right);
        const leftArrow = (node.left && node.left.val === node.val) ? left + 1 : 0;
        const rightArrow = (node.right && node.right.val === node.val) ? right + 1 : 0;
        ans = Math.max(ans, leftArrow + rightArrow);
